/**
 * Refuse NEW TypeScript diagnostics without pretending historical type debt
 * has disappeared. Both inputs must be generated by the same locked compiler.
 * Usage: node scripts/type-error-ratchet.mjs baseline.log head.log
 */
import { readFileSync } from "node:fs";

function parse(path) {
  const contents = readFileSync(path, "utf8");
  const map = new Map();
  for (const line of contents.split(/\r?\n/)) {
    const match = /^(.+?)\(\d+,\d+\): error TS(\d+): (.+)$/.exec(line.trim());
    if (!match) continue;
    const key = `${match[1]}:TS${match[2]}: ${match[3].replace(/\s+/g, " ").trim()}`;
    map.set(key, (map.get(key) ?? 0) + 1);
  }
  return map;
}

if (process.argv.length !== 4) {
  console.error("usage: node scripts/type-error-ratchet.mjs baseline.log head.log");
  process.exit(2);
}
const base = parse(process.argv[2]);
const head = parse(process.argv[3]);

const introduced = [];
for (const [diag, count] of head) {
  const difference = count - (base.get(diag) ?? 0);
  if (difference > 0) introduced.push(`${diag} (new: ${difference})`);
}

const count = (map) => [...map.values()].reduce((sum, num) => sum + num, 0);
console.log(`TypeScript baseline: ${count(base)} diagnostics; candidate: ${count(head)} diagnostics`);
if (introduced.length) {
  console.error("Type safety regression detected:");
  introduced.sort().forEach((diagnostic) => console.error(`  ${diagnostic}`));
  process.exit(1);
}
console.log("PASS: No introduced TypeScript diagnostics. Baseline debt remains tracked.");
